\label{thm:standard}
Fix $b\in\{1,3\}$ and $s\in\mathbb C$ such that $\operatorname{Re}(s)>(k+1)/2$. Then
\begin{align}\label{eq:standarduniform}
 \sup_{0\neq h\in S_k}
 \#\{p\in\mathscr P_{4,b}(X):L(h,\chi_p,s)=0\}=o(P_b(X)).
\end{align}
Equivalently, for any $\epsilon>0$, there exists some $X_0$ independent of $h$, such that 
$$\#\{p\in\mathscr P_{4,b}(X):L(h,\chi_p,s)=0\}<\epsilon P_b(X)$$
for every $X\geq X_0$ and every $0\neq h\in S_k$.

\label{thm:symmetric}
Fix $b\in\{1,3\}$ and $s\in\mathbb C$ such that $\operatorname{Re}(s)>k$. Then
\begin{align}\label{eq:symuniform}
 \sup_{\boldsymbol{c}\in\mathbb C^d\setminus\{0\}}
 \#\left\{p\in\mathscr P_{4,b}(X):
 \sum_{i=1}^dc_iL(\operatorname{Sym}^2f_i,\chi_p,s)=0\right\}=o(P_b(X)).
\end{align}
Equivalently, for any $\epsilon>0$, there exists some $X_0$ independent of $\boldsymbol{c}=(c_1,\ldots,c_d)$, such that 
$$\#\left\{p\in\mathscr P_{4,b}(X):
\sum_{i=1}^dc_iL(\operatorname{Sym}^2f_i,\chi_p,s)=0\right\}<\epsilon P_b(X)$$
for every $X\geq X_0$ and every $\boldsymbol{c}\in\mathbb C^d\setminus\{0\}$.

\label{cor:determinant}
Fix $b\in\{1,3\}$, $m\in\{1,2\}$, and $s\in\mathbb C$ with
$\operatorname{Re}(s)>\sigma_m$. Then
\begin{align}\label{eq:detcount}
 \#\left\{(p_1,\ldots,p_d)\in\mathscr P_{4,b}(X)^d:
 \det(L^{(m)}(f_i,\chi_{p_j},s))_{1\leq i,j\leq d}=0\right\}
 =o(P_b(X)^d).
\end{align}
Moreover, outside a set of $o(P_b(X)^d)$ tuples, the determinants are simultaneously nonzero for any fixed finite collection of pairs $(m,s)$ with $m\in\{1,2\}$ and $\operatorname{Re}(s)>\sigma_m$.

\label{rem:scope}
All the results above also hold with $\mathscr P_{4,b}(X)$ replaced by $\mathcal{P}_{\operatorname{odd}}(X)$ the set of odd primes up to $X$. 
All limits are taken with the weight, normalized Hecke eigenforms, and evaluation points fixed.

\label{thm:abstract}
Let $d\geq1$ and let $u_i(r)\in[-2,2]$ for every prime $r$ and
$1\leq i\leq d$. Suppose that, for each $i\neq j$, we have
\begin{align}\#\{r~{\rm prime}:u_i(r)\neq u_j(r)\}=\infty.\label{eq:abstractseparation}\end{align} Fix
$w\in\mathbb C$ with $\operatorname{Re}(w)>1$. Define
\begin{align*}
 Z_i&=\prod_r(1-u_i(r)\varepsilon_r r^{-w}+r^{-2w})^{-1},\\
 Y_i(p)&=\prod_r(1-u_i(r)\chi_p(r)r^{-w}
+\chi_p(r)^2r^{-2w})^{-1},
\end{align*}
where the products are over
all primes, and $r^{-w}:=\exp(-w\log r)$. Then these products converge absolutely and are nonzero. For every
$\boldsymbol{c}=(c_1,\ldots,c_d)\in\mathbb C^d\setminus\{0\}$,
\begin{align}
 \mu\left(\sum_{i=1}^d c_i Z_i=0\right)=0. \label{eq:randomsignP=0}
\end{align}
Moreover, for each $b\in\{1,3\}$,
\begin{align}
 \sup_{\boldsymbol{c}\neq0}
 \#\left\{p\in\mathscr P_{4,b}(X):\sum_{i=1}^d c_iY_i(p)=0\right\}
 =o(P_b(X)). \label{eq:twistP=0}
\end{align}

\label{prop:separationthm}
Let $f\in\mathcal H_k^{\operatorname{new}}(N,\omega)$ and
$g\in\mathcal H_k^{\operatorname{new}}(N',\omega)$ have the same weight and
character. Suppose that
\begin{align*}
 a_f(p)^2=a_g(p)^2
\end{align*}
for all primes $p$ outside a set $S$ of Dirichlet density
$\delta(S)<1/18$. Then there exists a quadratic character $\chi$
of conductor dividing $NN'$ such that
\begin{align*}
 a_f(p)=a_g(p)\chi(p)\qquad(p\nmid NN').
\end{align*}
If, in addition, $\omega$ is trivial and $N,N'$ are squarefree,
then $f=g$.

\label{lem:separation}
If $f,g\in\mathcal H_k$ are distinct, then
\begin{align*}
 a_f(r)^2\neq a_g(r)^2
\end{align*}
for infinitely many primes $r$. Consequently, each of the inequalities
$\lambda_f(r)\neq\lambda_g(r)$ and $b_f(r)\neq b_g(r)$ holds for
infinitely many primes.

\label{lem:signs}
Fix $b\in\{1,3\}$, distinct primes $r_1,\ldots,r_t$, and signs
$\eta_1,\ldots,\eta_t\in\{-1,1\}$. Then
\begin{align}\label{eq:signequidistribution}
 \lim_{X\longrightarrow\infty}
 \frac{\#\{p\in\mathscr P_{4,b}(X):\chi_p(r_j)=\eta_j\ (1\leq j\leq t)\}}
      {P_b(X)}=2^{-t}.
\end{align}

Let $N(X)$ denote the numerator in \eqref{eq:signequidistribution}. We may ignore the finitely many primes $p$ among  $r_1,\dots,r_t$ since they don't affect the limit. 
For an odd $r_j$, quadratic reciprocity gives
\begin{align*}
    \chi_p(r_j)=(-1)^{\frac{r_j-1}{2}\frac{p-1}{2}}\left(\frac{p}{r_j}\right).
\end{align*}
Since $p\equiv b\pmod 4$, $(-1)^{\frac{r_j-1}{2}\frac{p-1}{2}}$ is fixed. Thus, to make $\chi_p(r_j)=\eta_j$, $p$ must lie in a residue class modulo $r_j$ such that $\left(\frac{\cdot}{r_j}\right)$ has the required sign. Note that there are $(r_j-1)/2$ such nonzero residue classes modulo $r_j$.
For $r_j=2$, we have 
\begin{align*}
    \chi_p(2)=(-1)^{\frac{p^2-1}{8}}=\begin{cases}1& p\equiv1,7\pmod 8,\\ -1&p\equiv 3,5\pmod 8.\end{cases}
\end{align*}
Note that $p\equiv b\pmod 4$ gives $p\equiv b\pmod8$ or $p\equiv b+4 \pmod 8$, and each residue class gives different values of $\chi_p(2)$. Thus, to make $\chi_p(2)=\eta_j$, $p$ needs to lie in exactly one residue class modulo $8$.

Now, we write $\delta=1$ if some $r_j=2$ and $\delta=0$ otherwise. Then $t=\delta+\#\{j:r_j\neq2\}$. Let
$M=8\prod_{r_j\neq 2}r_j.$
By the Chinese remainder theorem and the argument above, there are
\begin{align*}
    2^{1-\delta}\prod_{r_j\neq2}\frac{r_j-1}{2}=\frac{\varphi(M)}{2^{t+1}}
\end{align*}
different residue classes modulo $M$ satisfying all conditions. Denote by $\mathcal{C}$ the set of these $\varphi(M)/2^{t+1}$ residue classes modulo $M$. Summing over  $\mathcal{C}$ and applying \eqref{eq:SiegelWalfisz}, we get 
\begin{align*}
N(X)&=\sum_{a\in\mathcal{C}}\pi(X;M,a)=|\mathcal{C}|\left(\frac{\operatorname{Li}(X)}{\varphi(M)}+o(\operatorname{Li}(X))\right)=2^{-(t+1)}\operatorname{Li}(X)+o(\operatorname{Li}(X)),
\end{align*}
which implies that
\begin{align*}
\lim_{X\rightarrow\infty}\frac{N(X)}{P_b(X)}&=\lim_{X\rightarrow\infty}\frac{2^{-(t+1)}\operatorname{Li}(X)+o(\operatorname{Li}(X))}{\frac{\operatorname{Li}(X)}{\varphi(4)}+o(\operatorname{Li}(X))}=2^{-t},
\end{align*}
as desired.

\label{lem:uniformproduct}
The products in \eqref{eq:abstractY} converge absolutely and uniformly
in $\boldsymbol{e}$, and their values are nonzero. The set
\begin{align}
 K=Y\left(\{-1,0,1\}^{\{{\rm primes}\}}\right) \label{eq:compactK}
\end{align}
is a compact subset of $(\mathbb C^\times)^d$. Moreover, for $R\geq2$,
\begin{align}\label{eq:uniformtail}
 \sup_{\boldsymbol{e}}\left|Y_i(\boldsymbol{e})-\prod_{r\leq R}V_{i,r}(e_r)\right|
 \ll_w\sum_{r>R}r^{-\sigma}
 \qquad(1\leq i\leq d).
\end{align}

\label{lem:blockconditioning}
Let $B$ be a finite set of primes and
$\mathcal G_B=\sigma(\varepsilon_r:r\notin B)$ be the $\sigma$-algebra generated by the events $\{\varepsilon_r=1\}$ for $r\notin B$.
For $\omega\in\Omega$ and $\eta\in\{-1,1\}^B$, let
$\omega^{B,\eta}$ be obtained by replacing the coordinates of $\omega$
in $B$ by $\eta$. Then, for every $A\in\mathcal F$,
\begin{align}\label{eq:blockconditioning}
 \mu(A\mid\mathcal G_B)(\omega)
 =2^{-|B|}\sum_{\eta\in\{-1,1\}^B}
   \mathbf1_A(\omega^{B,\eta})
 \qquad\text{almost surely}.
\end{align}

\label{lem:conditionalgap}
For every $A\in\mathcal F$,
\begin{align}\label{eq:conditionalconvergence}
 \mathbb E|\mu(A\mid\mathcal F_n)-\mathbf1_A|
 \longrightarrow0,\qquad n\rightarrow\infty.
\end{align}
Consequently, if there is $\delta>0$ such that
$\mu(A\mid\mathcal F_n)\leq1-\delta$ almost surely for every $n$,
then $\mu(A)=0$.

\label{prop:non-concentration}
For every $\boldsymbol{c}=(c_1,\ldots,c_d)\in\mathbb C^d\setminus\{0\}$,
\begin{align}\label{eq:randomzero}
\mu\left(\sum_{i=1}^dc_iZ_i=0\right)=0.
\end{align}

For $d=1$, the result follows from the non-vanishing in Lemma~\ref{lem:uniformproduct}.
Suppose $d\geq2$, fix $\boldsymbol{c}\neq0$, and put
$$A=\left\{\sum_i c_iZ_i=0\right\},\qquad M=\binom d2.$$
For each prime $r$, let $v_{i,r}(e)=V_{i,r}(e)$ for $e\in\{-1,1\}$, whose
 values are nonzero. Writing $t=r^{-w}$, we have by definition \eqref{eq:localV} that 
\begin{align*}
 \frac{V_{i,r}(1)}{V_{i,r}(-1)}
 =\frac{1+u_i(r)t+t^2}{1-u_i(r)t+t^2}.
\end{align*}
It follows that
\begin{align}\label{eq:localindependent}
 v_{i,r}\not\parallel v_{j,r}
 \quad&\Longleftrightarrow\quad 2t(1+t^2)(u_i(r)-u_j(r))\neq0\nonumber\\&\Longleftrightarrow\quad u_i(r)\neq u_j(r).
\end{align}

For fixed $n$ and each pair $i<j$, choose a prime $r_{ij}>r_n$ with $u_i(r_{ij})\neq u_j(r_{ij})$, making all choices distinct. This is possible by the assumption \eqref{eq:abstractseparation}, and at each choice we only exclude the first $n$ primes and the primes previously chosen.   Put
\begin{align*}
 B_n=\{r_{ij}:i<j\},\qquad
 \mathcal G_n=\sigma(\varepsilon_r:r\notin B_n).
\end{align*}
Then $|B_n|=M$, and Lemma~\ref{lem:tensors} implies that 
\begin{align*}
 F_i(\eta)=\prod_{r\in B_n}V_{i,r}(\eta_r)
 \qquad(\eta\in\{-1,1\}^{B_n}, 1\leq i\leq d),
\end{align*}
are linearly independent. Note that for any $R\geq\max B_n$, we have 
\begin{align*}
    \prod_{r\leq R}V_{i,r}(\varepsilon_r)=\left(\prod_{r\in B_n}V_{i,r}(\varepsilon_r)\right)\prod_{r\leq R,r\notin B_n}V_{i,r}(\varepsilon_r).
\end{align*}
Then Lemma \ref{lem:uniformproduct} gives
\begin{align*}
    Z_i=D_iF_i\left((\varepsilon_r)_{r\in B_n}\right),\qquad D_i:=\prod_{r\notin B_n}V_{i,r}(\varepsilon_r), \qquad (1\leq i\leq d),
\end{align*}
where $D_i$'s are nonzero. Hence $c_i D_i$'s are not all zero, and the linear independence of $F_i$'s implies that $\sum_{i=1}^dc_i D_iF_i(\eta)$ is nonzero for at least one $\eta$. It follows from Lemma~\ref{lem:blockconditioning} that 
\begin{align*}\mu(A\mid \mathcal{G}_n)&=2^{-|B_n|}\sum_{\eta\in\{-1,1\}^{B_n}}\mathbf{1}_A(\omega^{B_n,\eta})\\&\leq 2^{-M}(2^M-1)\\&=1-2^{-M}\qquad{\rm almost~surely}.\end{align*}

Finally, note that $\mathcal{F}_n\subseteq\mathcal{G}_n$, then the tower property \eqref{eq:tower} gives 
\begin{align*}
    \mu(A\mid \mathcal{F}_n)&= \mathbb E(\mu(A\mid\mathcal G_n)\mid\mathcal F_n)\\&\leq 1-2^{-M}\qquad{\rm almost~surely}.
\end{align*}
Therefore, we have $\mu(A)=0$ from Lemma \ref{lem:conditionalgap}, completing the proof.

\label{lem:compactness}
Let $\nu_n$ and $\nu$ be probability measures supported on a common
compact set $K\subseteq\mathbb C^d$. Suppose $\nu_n\Longrightarrow\nu$
and $\nu(H)=0$ for every complex linear hyperplane $H$ through the
origin. Then
\begin{align*}
 \sup_H\nu_n(H)\longrightarrow0,
\end{align*}
where the supremum is over these hyperplanes.

\label{prop:primeproducts}
Under \eqref{eq:abstractseparation}, for each $b\in\{1,3\}$,
\begin{align}\label{eq:abstractuniform}
 \sup_{\boldsymbol{c}\neq0}
 \#\{p\in\mathscr P_{4,b}(X):\boldsymbol{c}\cdot Y(p)=0\}=o(P_b(X)).
\end{align}

We first show that $\nu_X\Longrightarrow\nu$.
Fix a bounded continuous function $\varphi:\mathbb C^d\to\mathbb R$.
For $R\geq2$, define the truncated coordinates and random vectors by
\begin{align*}
 Y_{i,R}(p)&=\prod_{r\leq R}V_{i,r}(\chi_p(r)),
 &Z_{i,R}&=\prod_{r\leq R}V_{i,r}(\varepsilon_r),\\
 Y_R(p)&=(Y_{1,R}(p),\ldots,Y_{d,R}(p)),
 &Z_R&=(Z_{1,R},\ldots,Z_{d,R}),
\end{align*}
where the products are over primes. The values of $Y_R$ and $Z_R$ lie in the compact set $K$ defined in \eqref{eq:compactK}.
Fix $R$. Let $r_1<\cdots<r_t$ be the primes at most $R$.
For $\eta=(\eta_1,\ldots,\eta_t)\in\{-1,1\}^t$,
put
\begin{align*}
 y_R(\eta)&=
 \left(\prod_{j=1}^tV_{1,r_j}(\eta_j),\ldots,
       \prod_{j=1}^tV_{d,r_j}(\eta_j)\right),\\
 N_X(\eta)&=
 \#\{p\in\mathscr P_{4,b}(X):p>R,\
       \chi_p(r_j)=\eta_j\text{ for }1\leq j\leq t\}.
\end{align*}

Note that for $p>R$, we have  $\chi_p(r_j)\neq0$, $\eta=(\chi_{p}(r_1),\ldots,\chi_p(r_{t}))\in\{-1,1\}^t$, and $Y_R(p)=y_R(\eta)$. It follows that
\begin{align}\label{eq:midstep}
 \frac1{P_b(X)}
 \sum_{\substack{p\in\mathscr P_{4,b}(X)\\p>R}}\varphi(Y_R(p))
 &=\frac{1}{P_b(X)}\sum_{\eta\in\{-1,1\}^t}\sum_{\substack{p\in\mathscr P_{4,b}(X), ~p>R\\\chi_p(r_j)=\eta_j~(1\leq j\leq t)}}\varphi(y_R(\eta))\nonumber\\&=
 \sum_{\eta\in\{-1,1\}^t}
   \frac{N_X(\eta)}{P_b(X)}\,\varphi(y_R(\eta))\nonumber\\&\longrightarrow 2^{-t}\sum_{\eta\in\{-1,1\}^t}\varphi(y_R(\eta)),\qquad X\rightarrow\infty,
\end{align}
where we used the fact $N_X(\eta)/P_b(X)\rightarrow 2^{-t}$ by Lemma~\ref{lem:signs}. Note also that
\begin{align}
 \left|
 \frac1{P_b(X)}
 \sum_{\substack{p\in\mathscr P_{4,b}(X)\\p\leq R}}
 \varphi(Y_R(p))
 \right|
 \leq \frac{t}{P_b(X)}\sup_{z\in K}|\varphi(z)|
 \longrightarrow0,\qquad X\rightarrow\infty. \label{eq:midstepp<R}
\end{align}
Here $R$ and $t$ are fixed, $\varphi$ is bounded on the compact set $K$,
and $P_b(X)\to\infty$. 

On the other hand, for each $\eta=(\eta_1,\ldots,\eta_t)\in\{-1,1\}^t$, let $E_{\eta}$ denote the event $\{\varepsilon_{r_j}=\eta_j:1\leq j\leq t\}$.
Then the independence of $(\varepsilon_r)_r$ gives
\begin{align*}
\mu(E_{\eta})
=\prod_{j=1}^t\mu(\varepsilon_{r_j}=\eta_j)
 =2^{-t}.
\end{align*}
Note that we have  $Z_R=y_R(\eta)$ on $E_{\eta}$. Since $\Omega=\bigsqcup_{\eta\in\{-1,1\}^t} E_{\eta}$, we have
\begin{align}
 \mathbb E\varphi(Z_R)
 =&\sum_{\eta\in\{-1,1\}^t}\int_{E_{\eta}}\varphi(Z_R)d\mu\nonumber\\=&\sum_{\eta\in\{-1,1\}^t}
   \varphi(y_R(\eta))\,
\mu(E_{\eta})\nonumber\\
 =&2^{-t}\sum_{\eta\in\{-1,1\}^t}\varphi(y_R(\eta)).\label{eq:midstepZ_R}
\end{align}
Thus, by \eqref{eq:midstep}, \eqref{eq:midstepp<R}, and \eqref{eq:midstepZ_R}, we have
\begin{align}\label{eq:truncatedlimit}
\lim_{X\to\infty}\frac1{P_b(X)}
 \sum_{p\in\mathscr P_{4,b}(X)}\varphi(Y_R(p))
 =2^{-t}\sum_{\eta\in\{-1,1\}^t}\varphi(y_R(\eta))
 =\mathbb E\varphi(Z_R).
\end{align}

We now remove the truncation. Lemma~\ref{lem:uniformproduct} gives
$Y_R(p)\to Y(p)$ uniformly in $p$ and $Z_R(\omega)\to Z(\omega)$
uniformly in $\omega\in\Omega$. Since all these random vectors lie in $K$,
uniform continuity of $\varphi$ on $K$ gives a common bound
$\epsilon_R\to0$ such that
\begin{align}
 |\varphi(Y(p))-\varphi(Y_R(p))|\leq\epsilon_R,\qquad
 |\varphi(Z(\omega))-\varphi(Z_R(\omega))|\leq\epsilon_R\label{eq:midstepuniformbd}
\end{align}
for every odd prime $p$ and every $\omega\in\Omega$.
Hence \eqref{eq:truncatedlimit} and \eqref{eq:midstepuniformbd}  give
\begin{align*}
 \limsup_{X\to\infty}
 \left|\int\varphi\,d\nu_X-\int\varphi\,d\nu\right|
 \leq2\epsilon_R.
\end{align*}
Letting $R\to\infty$ proves the weak convergence $\nu_X\Longrightarrow\nu$.

Finally, note that
Proposition~\ref{prop:non-concentration} gives
\begin{align*}
 \nu(H_{\boldsymbol{c}})=\mu\left(\sum_{i=1}^d c_iZ_i=0\right)=0
 \qquad(\boldsymbol{c}\neq0).
\end{align*}
As both $\nu$ and $\nu_X$ are supported on a compact set $K$, we can apply
Lemma \ref{lem:compactness},  along any sequence $X\to\infty$,
giving
\begin{align*}
 \sup_{\boldsymbol{c}\neq0}\nu_X(H_{\boldsymbol{c}})
 =\frac1{P_b(X)}\sup_{\boldsymbol{c}\neq0}
   \#\{p\in\mathscr P_{4,b}(X):\boldsymbol{c}\cdot Y(p)=0\}
 \longrightarrow0,
\end{align*}
which proves \eqref{eq:abstractuniform}.

\label{thm:kernelconstruction}
For an odd prime $p$, the series
\begin{align}
 K^{(1)}_{k,p,s}(z)
 &=\sum_{n\geq1}\frac{\chi_p(n)}{n^{\overline{s}}}Q_{k,n}(z),
 &&\operatorname{Re}(s)>(k+1)/2,\label{eq:standardkernel}\\
 K^{(2)}_{k,p,s}(z)
 &=\overline{D_p(s)}\sum_{n\geq1}
 \frac{\chi_p(n)}{n^{\overline{s}}}Q_{k,n^2}(z),
 &&\operatorname{Re}(s)>k\label{eq:symkernel}
\end{align}
converge absolutely in Petersson norm and locally uniformly on
$\mathbb H$. For $m\in\{1,2\}$ and $\operatorname{Re}(s)>\sigma_m$, the resulting
form is the unique element of $S_k$ satisfying
\begin{align}\label{eq:kernelpairing}
 \langle h,K^{(m)}_{k,p,s}\rangle=\mathcal L^{(m)}_{p,s}(h)
 \qquad(h\in S_k),
\end{align}
and its spectral expansion is
\begin{align}\label{eq:kernelspectral}
 K^{(m)}_{k,p,s}
 =\sum_{i=1}^d\frac{\overline{L^{(m)}(f_i,\chi_p,s)}}{N_i}f_i.
\end{align}

\label{thm:kernelspanning}
Fix $b\in\{1,3\}$, $m\in\{1,2\}$, and $s$ with
$\operatorname{Re}(s)>\sigma_m$. Then
\begin{align}\label{eq:kerneluniform}
 B_{m,s,b}(X):=\sup_{W\subsetneq S_k}
 \#\{p\in\mathscr P_{4,b}(X):K^{(m)}_{k,p,s}\in W\}
 =o(P_b(X)),
\end{align}
where $W$ runs over proper complex linear subspaces of $S_k$.
Consequently:
\begin{enumerate}
 \item For every $\delta>0$, there exists $X_0$ such that, for every
 $X\geq X_0$ and every $\mathcal A_X\subseteq\mathscr P_{4,b}(X)$ with
 $\#\mathcal A_X\geq\delta P_b(X)$,
 \begin{align*}
  \operatorname{Span}_{\mathbb C}\{K^{(m)}_{k,p,s}:p\in\mathcal A_X\}=S_k.
 \end{align*}
 \item If $\mathcal A\subseteq\mathscr P_{4,b}$ satisfies
 $\overline\delta_b(\mathcal A)>0$, then, for every $Y>0$,
 \begin{align*}
  \operatorname{Span}_{\mathbb C}\{K^{(m)}_{k,p,s}:p\in\mathcal A,\ p>Y\}=S_k.
 \end{align*}
 \item Almost every ordered tuple $(p_1,\ldots,p_d)\in\mathscr P_{4,b}(X)^d$
 gives a basis $K^{(m)}_{k,p_1,s},\ldots,K^{(m)}_{k,p_d,s}$ of $S_k$.
\end{enumerate}
The estimate \eqref{eq:kerneluniform} and assertions (i)--(iii) hold
simultaneously for any fixed finite collection of pairs $(m,s)$ with
$m\in\{1,2\}$ and $\operatorname{Re}(s)>\sigma_m$.

\label{cor:periods}
Fix $b\in\{1,3\}$. Outside a set of $o(P_b(X)^d)$ tuples
$(p_1,\ldots,p_d)\in\mathscr P_{4,b}(X)^d$, the periods
\begin{align*}
r_{t,\chi_{p_1}},\ldots,r_{t,\chi_{p_d}}
\end{align*}
form a basis of $S_k^*$ simultaneously for every integer
\begin{align*}
 0\leq t\leq k/2-2\qquad\text{or}\qquad k/2\leq t\leq k-2.
\end{align*}

Since $f_1,\ldots,f_d$ form a basis of $S_k$, the periods form a
basis of $S_k^*$ exactly when the matrix
$R_t=(r_{t,\chi_{p_j}}(f_i))_{i,j=1}^d$ is nonsingular.
If $k/2\leq t\leq k-2$, then
\begin{align*}
 \det R_t
 =\left(\frac{t!}{(-2\pi i)^{t+1}}\right)^d
\det(L(f_i,\chi_{p_j},t+1))_{1\leq i,j\leq d}.
\end{align*}
Here $t+1\geq k/2+1>(k+1)/2$, so
Corollary~\ref{cor:determinant} applies.

Now suppose $0\leq t\leq k/2-2$. For $f\in\mathcal H_k$, put
\begin{align*}
 \Lambda_{f,p}(s)
 =\left(\frac p{2\pi}\right)^s\Gamma(s)L(f,\chi_p,s).
\end{align*}
The quadratic-twist functional equation
\cite[Chapter~14]{IwaniecKowalski2004}, in the normalization recorded
in \cite[Section~2.1]{Ni2026}, is
\begin{align*}
 \Lambda_{f,p}(s)=i^k\chi_p(-1)\Lambda_{f,p}(k-s).
\end{align*}
Consequently,
\begin{align*}
 L(f,\chi_p,s)
 &=i^k\chi_p(-1)\left(\frac p{2\pi}\right)^{k-2s}
 \frac{\Gamma(k-s)}{\Gamma(s)}L(f,\chi_p,k-s).
\end{align*}
Setting $s=t+1$ and using \eqref{eq:defoftwistperiod} gives
\begin{align*}
 r_{t,\chi_{p_j}}(f_i)
 &=C_{p_j,t}L(f_i,\chi_{p_j},k-t-1),\\
 C_{p,t}
 &:=\frac{i^k\chi_p(-1)(k-t-2)!}{(-2\pi i)^{t+1}}
 \left(\frac p{2\pi}\right)^{k-2t-2},
\end{align*}
where the factor $C_{p,t}$ is nonzero and independent of $f_i$. Hence
\begin{align*}
 \det R_t
 =\left(\prod_{j=1}^d C_{p_j,t}\right)
 \det(L(f_i,\chi_{p_j},k-t-1))_{i,j=1}^d.
\end{align*}
Since $k-t-1\geq k/2+1>(k+1)/2$,
Corollary~\ref{cor:determinant} also applies in this range.
Finally, since there are only finitely many admissible indices $t$, the union
of their exceptional sets still has size $o(P_b(X)^d)$.

\label{cor:rationalbases}
All but $o(\pi(X;4,(-1)^{k_1})^{d_K})$ ordered $d_K$-tuples of primes
$p_j\leq X$, $p_j\equiv(-1)^{k_1}\pmod4$, give a basis
\begin{align*}
 F_{p_1},\ldots,F_{p_{d_K}}
\end{align*}
of $S_K$ consisting of forms with rational Fourier coefficients.

Let $\mathcal H_K=\{f_1,\ldots,f_{d_K}\}$ be the
normalized Hecke eigenbasis of $S_K$.
For $f\in\mathcal H_K$, the Rankin--Selberg identity recalled in
\cite[Lemma 2.1]{Ni2026} gives
\begin{align}
 \langle f,F_p\rangle
 =C_pL(f,k_1+k_2+c-1)L(f,\chi_p,k_2+c),\label{eq:rankinselbergid}
\end{align}
where $C_p\neq0$ is independent of $f$. Since $k_1$ and $k_2$ have
the same parity, $k_2\geq k_1+2$, and hence
\begin{align*}
 k_2+c>(K+1)/2,\qquad k_1+k_2+c-1>(K+1)/2.
\end{align*}
Hence both $L$-values in \eqref{eq:rankinselbergid} are nonzero. Define
\begin{align*}
 A=(\langle f_i,F_{p_j}\rangle)_{1\leq i,j\leq d_K},\qquad
 M=(L(f_i,\chi_{p_j},k_2+c))_{1\leq i,j\leq d_K}.
\end{align*}
Since the $f_i$ span $S_K$, a form orthogonal to all of them must be zero.
Thus, for every column vector $\boldsymbol{c}=(c_1,\ldots,c_{d_K})^T$,
\begin{align*}
 A\overline{\boldsymbol{c}}=0
 \quad\Longleftrightarrow\quad
 \sum_{j=1}^{d_K}c_jF_{p_j}=0.
\end{align*}
Consequently, $A$ is nonsingular exactly when the $F_{p_j}$ are
linearly independent. Equation~\eqref{eq:rankinselbergid} gives
\begin{align*}
 A={}&\operatorname{diag}(L(f_i,k_1+k_2+c-1))_{i=1}^{d_K}
 \,M\,\operatorname{diag}(C_{p_j})_{j=1}^{d_K}.
\end{align*}
Note that both diagonal matrices are invertible, so $A$ is nonsingular exactly
when $M$ is. Corollary~\ref{cor:determinant}, applied in weight $K$,
proves the assertion.

\label{thm:explicitbases}
Suppose that $d=\dim S_k\in\{2,3\}$, and let $p_1,\ldots,p_d$
be odd primes satisfying the following conditions:
\begin{enumerate}
 \item If $d=2$, then $\chi_{p_1}(2)\neq\chi_{p_2}(2)$.
 \item If $d=3$, then $p_j>3$ for every $j$, and the three pairs
 \begin{align*}
  (\chi_{p_j}(2),\chi_{p_j}(3)),\qquad 1\leq j\leq3,
 \end{align*}
 are pairwise distinct.
\end{enumerate}
For $m\in\{1,2\}$ and every complex number $s$ with $\operatorname{Re}(s)\geq\sigma_m+17$,
\begin{align}\label{eq:explicitdet}
 \det(L^{(m)}(f_i,\chi_{p_j},s))_{1\leq i,j\leq d}\neq0.
\end{align}
Thus $\mathcal L^{(m)}_{p_1,s},\ldots,\mathcal L^{(m)}_{p_d,s}$ form a basis of
$S_k^*$, and $K^{(m)}_{k,p_1,s},\ldots,K^{(m)}_{k,p_d,s}$ form a basis of $S_k$.

\label{lem:smallcoefficientdet}
For $d=\dim S_k\in\{2,3\}$ and $m\in\{1,2\}$, put
\begin{align}\label{eq:smallcoefficientdet}
D_{k,m}=\det(c_i(j))_{1\leq i,j\leq d}.
\end{align}
Then $|D_{k,m}|\geq1/4$.

\label{lem:determinantexpansion}
Suppose $d\geq2$. For any odd primes $p_1,\ldots,p_d$ and $w\in\mathbb C$
with $\operatorname{Re}(w)>1$,
\begin{align}\label{eq:determinantexpansion}
 \det(F_{i,p_j}(w))_{1\leq i,j\leq d}
 =\sum_{1\leq n_1<\cdots<n_d}
\frac{\det(c_i(n_\ell))_{1\leq i,\ell\leq d}
      \cdot \det(\chi_{p_j}(n_\ell))_{1\leq \ell,j\leq d}}
      {(n_1\cdots n_d)^w},
\end{align}
and the series converges absolutely.

Put $u=\operatorname{Re}(w)>1$. For $N\geq d$, define the $d\times N$ and $N\times d$ matrices
\begin{align*}
 A_N&=(c_i(n)n^{-w})_{1\leq i\leq d,1\leq n\leq N},
 &C_N&=(\chi_{p_j}(n))_{\substack{1\leq n\leq N,1\leq j\leq d}},
\end{align*}
which gives
\begin{align*}
 M_N=A_NC_N
 =\left[\sum_{n\leq N}c_i(n)\chi_{p_j}(n)n^{-w}\right]_{1\leq i,j\leq d}.
\end{align*}
By the Cauchy--Binet formula \cite[p.~28]{Hornbook}, we have
\begin{align}\label{eq:finitecauchybinet}
 \det M_N
 =\sum_{1\leq n_1<\cdots<n_d\leq N}
 \frac{\det(c_i(n_\ell))_{1\leq i,\ell\leq d}
    \cdot\det(\chi_{p_j}(n_\ell))_{1\leq \ell,j\leq d}}
      {(n_1\cdots n_d)^w}.
\end{align}
Let $M=(F_{i,p_j}(w))_{1\leq i,j\leq d}$.
By \eqref{eq:reducedcoefficients} and $|n^{-w}|=n^{-u}$,
\begin{align*}
 \max_{i,j}|(M_N)_{ij}-M_{ij}|
 \leq\sum_{n>N}\frac{\tau(n)}{n^u}\longrightarrow0
 \qquad(N\to\infty),
\end{align*}
since $\sum_{n\geq1}\tau(n)n^{-u}=\zeta(u)^2<\infty$.
Continuity of the determinant therefore gives
\begin{align*}
 \lim_{N\to\infty}\det M_N=\det M.
\end{align*}
Hadamard's inequality \cite[p.~506]{Hornbook} and
$|\chi_{p_j}(n)|\leq1$ give
\begin{align}\label{eq:minorbound}
\left|\det(c_i(n_\ell))_{1\leq i,\ell\leq d}\cdot
       \det(\chi_{p_j}(n_\ell))_{1\leq \ell,j\leq d}\right|
 \leq d^d\prod_{\ell=1}^d\tau(n_\ell).
\end{align}
Consequently, for every integer $N\geq d$,
\begin{align}
 &\sum_{\substack{1\leq n_1<\cdots<n_d\nonumber\\ n_d>N}} \frac{\left|\det(c_i(n_\ell))_{1\leq i,\ell\leq d}
    \cdot\det(\chi_{p_j}(n_\ell))_{1\leq \ell,j\leq d}\right|}
      {(n_1\cdots n_d)^u}\\&\leq
 d^d\sum_{t>N}\frac{\tau(t)}{t^u}
       \sum_{n_1<\cdots<n_{d-1}<t}
       \prod_{\ell=1}^{d-1}\frac{\tau(n_\ell)}{n_\ell^u}\nonumber\\&
 \leq\frac{d^d\zeta(u)^{2d-2}}{(d-1)!}
\sum_{t>N}\frac{\tau(t)}{t^u},\label{eq:middlestep}
\end{align}
where we used the fact
\begin{align*}
 (d-1)!\sum_{n_1<\cdots<n_{d-1}<t}
       \prod_{\ell=1}^{d-1}\frac{\tau(n_\ell)}{n_\ell^u}
 &\leq \sum_{n_1,\ldots,n_{d-1}\geq1}
       \prod_{\ell=1}^{d-1}\frac{\tau(n_\ell)}{n_\ell^u}\\
 &=\left(\sum_{n\geq1}\frac{\tau(n)}{n^u}\right)^{d-1}
 \\&=\zeta(u)^{2d-2}.
\end{align*}
Taking $N=d$ in \eqref{eq:middlestep} proves absolute convergence
of the tail with $n_d>d$. The only remaining tuple is
$(1,\ldots,d)$, so the whole series in
\eqref{eq:determinantexpansion} converges absolutely.
As $N\to\infty$, the bound in \eqref{eq:middlestep} tends to zero,
so the finite sums in
\eqref{eq:finitecauchybinet} converge to the series in
\eqref{eq:determinantexpansion}. Together with
$\det M_N\to\det M$, this proves the identity.

Put $w=s-\sigma_m+1$, $u=\operatorname{Re}(w)$, and
$B=(\chi_{p_j}(n))_{1\leq n,j\leq d}$.
For $d=2$, condition~(i) gives $|\det B|=2$.
For $d=3$, its columns are $(1,\epsilon_j,\eta_j)^T$, where
the $(\epsilon_j,\eta_j)$ are three distinct elements of
$\{-1,1\}^2$. Every such choice gives $|\det B|=4$.

Separating the term $(n_1,\ldots,n_d)=(1,\ldots,d)$ from
the remaining terms in \eqref{eq:determinantexpansion}, we write
\begin{align}\label{eq:leadingdeterminant}
 \det(F_{i,p_j}(w))_{1\leq i,j\leq d}=D_{k,m}(\det B)(d!)^{-w}+E_d(w).
\end{align}
Let $Q_2=3$ and $Q_3=10$. Every nonzero term in $E_d(w)$ has
$n_1\cdots n_d\geq Q_d$. For $d=2$ this is immediate.
For $d=3$, the only remaining triple with product less than $10$
is $(1,2,4)$; the corresponding determinant $\det(\chi_{p_j}(n_\ell))_{1\leq\ell,j\leq3}$ vanishes because
$\chi_{p_j}(1)=\chi_{p_j}(4)=1$ for every $j$.
By \eqref{eq:minorbound}, for
$u\geq2$ we obtain
\begin{align*}
 |E_d(w)|
 &\leq d^dQ_d^{2-u}
 \sum_{n_1<\cdots<n_d}
       \prod_{\ell=1}^d\frac{\tau(n_\ell)}{n_\ell^2}\\
 &\leq\frac{d^d}{d!}Q_d^{2-u}\zeta(2)^{2d}.
\end{align*}




In particular,
\begin{align}\label{eq:determinanttails}
 |E_2(w)|\leq18\zeta(2)^4\,3^{-u},\qquad
 |E_3(w)|\leq450\zeta(2)^6\,10^{-u}.
\end{align}
For either $m\in\{1,2\}$, Lemma~\ref{lem:smallcoefficientdet}
gives $|D_{k,m}|\geq1/4$. Hence the leading term in
\eqref{eq:leadingdeterminant} satisfies
\begin{align*}
 |D_{k,m}(\det B)(d!)^{-w}|
 =|D_{k,m}\det B|(d!)^{-u}
 \geq\begin{cases}
 \frac12\,2^{-u},&d=2,\\
 6^{-u},&d=3.
 \end{cases}
\end{align*}
For $u\geq18$, the bounds in \eqref{eq:determinanttails} give
\begin{align*}
 \frac{|E_2(w)|}{\frac12\,2^{-u}}
 &\leq36\zeta(2)^4\left(\frac23\right)^u<1,\\
 \frac{|E_3(w)|}{6^{-u}}
 &\leq450\zeta(2)^6\left(\frac35\right)^u<1.
\end{align*}
Thus, the leading term in \eqref{eq:leadingdeterminant} strictly exceeds the error term $E_d(w)$ in absolute
value, and $\det(F_{i,p_j}(w))\neq0$ for
$u\geq18$, equivalently $\operatorname{Re}(s)\geq\sigma_m+17$.
For $m=2$, the Euler product gives $L(w,\chi_{p_j})\neq0$
when $\operatorname{Re}(w)>1$. Multiplying the $j$th column of
$(F_{i,p_j}(w))_{1\leq i,j\leq d}$ by this factor recovers
the matrix in \eqref{eq:explicitdet}.
The matrix $(\mathcal L^{(m)}_{p_j,s}(f_i))_{1\leq i,j\leq d}$
is therefore nonsingular, so these $d$ linear functionals form a
basis of $S_k^*$. The kernel representation \eqref{eq:kernelspectral}
then gives the corresponding basis of $S_k$.

Suppose that $d=\dim S_k\in\{2,3\}$. Fix $m\in\{1,2\}$ and an
integer $\ell>\sigma_m$. Do we have
\begin{align*}
 \det(L^{(m)}(f_i,\chi_{p_j},\ell))_{1\leq i,j\leq d}\neq0
\end{align*}
for every $d$-tuple of distinct odd primes $p_1,\ldots,p_d$?
